import React, { useState, useEffect } from 'react';
import { newsletterApi, ApiError } from './services/api';
import { ProcessingStage, AppState } from './types/newsletter';
import TopicInput from './components/Newsletter/TopicInput';
import ProcessingStages from './components/Newsletter/ProcessingStages';
import NewsletterOutput from './components/Newsletter/NewsletterOutput';
import QualityScore from './components/Newsletter/QualityScore';
import './styles/globals.css';

// Define the 5-stage processing pipeline
const initialStages: ProcessingStage[] = [
  {
    id: 'search-planning',
    name: 'Smart Search Planning',
    description: 'AI analyzes your topic and creates targeted search strategies',
    icon: '🧠',
    status: 'pending'
  },
  {
    id: 'content-research',
    name: 'Content Research',
    description: 'Searching the web for the latest and most relevant information',
    icon: '🔍',
    status: 'pending'
  },
  {
    id: 'newsletter-creation',
    name: 'Newsletter Creation',
    description: 'Crafting your professional newsletter with AI-powered writing',
    icon: '✍️',
    status: 'pending'
  },
  {
    id: 'quality-assessment',
    name: 'Quality Assessment',
    description: 'Evaluating newsletter quality across multiple metrics',
    icon: '📊',
    status: 'pending'
  },
  {
    id: 'auto-improvement',
    name: 'Auto-Improvement',
    description: 'Refining and enhancing the newsletter for maximum impact',
    icon: '🔧',
    status: 'pending'
  }
];

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>({
    isGenerating: false,
    currentStage: 0,
    stages: initialStages,
    newsletter: null,
    error: null,
    topic: ''
  });

  const [apiHealth, setApiHealth] = useState<boolean | null>(null);
  const [showHero, setShowHero] = useState(true);

  // Check API health on component mount
  useEffect(() => {
    checkApiHealth();
  }, []);

  const checkApiHealth = async () => {
    try {
      const isHealthy = await newsletterApi.testConnection();
      setApiHealth(isHealthy);
    } catch (error) {
      setApiHealth(false);
    }
  };

  const resetState = () => {
    setAppState({
      isGenerating: false,
      currentStage: 0,
      stages: initialStages.map(stage => ({ ...stage, status: 'pending' })),
      newsletter: null,
      error: null,
      topic: ''
    });
    setShowHero(true);
  };

  const updateStageStatus = (stageIndex: number, status: ProcessingStage['status'], duration?: number) => {
    setAppState(prev => ({
      ...prev,
      stages: prev.stages.map((stage, index) => 
        index === stageIndex 
          ? { 
              ...stage, 
              status, 
              duration,
              endTime: status === 'completed' ? new Date() : stage.endTime,
              startTime: status === 'processing' ? new Date() : stage.startTime
            }
          : stage
      ),
      currentStage: status === 'completed' ? stageIndex + 1 : stageIndex
    }));
  };

  const simulateProcessingStages = async () => {
    const stageDurations = [2.3, 18.7, 12.1, 3.8, 11.2]; // Realistic durations
    
    for (let i = 0; i < initialStages.length; i++) {
      updateStageStatus(i, 'processing');
      
      // Simulate processing time
      await new Promise(resolve => setTimeout(resolve, 1000)); // Visual feedback delay
      
      updateStageStatus(i, 'completed', stageDurations[i]);
      
      // Small delay between stages
      if (i < initialStages.length - 1) {
        await new Promise(resolve => setTimeout(resolve, 500));
      }
    }
  };

  const handleTopicSubmit = async (topic: string) => {
    setShowHero(false);
    setAppState(prev => ({
      ...prev,
      isGenerating: true,
      topic,
      error: null,
      newsletter: null,
      currentStage: 0,
      stages: initialStages.map(stage => ({ ...stage, status: 'pending' }))
    }));

    try {
      // Start the visual processing simulation
      const processingPromise = simulateProcessingStages();
      
      // Start the actual API call
      const apiPromise = newsletterApi.generateNewsletter(topic);
      
      // Wait for both to complete
      const [newsletter] = await Promise.all([apiPromise, processingPromise]);
      
      setAppState(prev => ({
        ...prev,
        isGenerating: false,
        newsletter,
        error: null
      }));

    } catch (error) {
      const apiError = error as ApiError;
      
      // Mark current stage as error
      setAppState(prev => ({
        ...prev,
        isGenerating: false,
        error: apiError.detail || 'An unexpected error occurred',
        stages: prev.stages.map((stage, index) => 
          index === prev.currentStage 
            ? { ...stage, status: 'error' }
            : stage
        )
      }));
    }
  };

  const handleGenerateAnother = () => {
    resetState();
    // Scroll to top
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const scrollToGenerator = () => {
    setShowHero(false);
    // Small delay for smooth transition
    setTimeout(() => {
      const generatorSection = document.getElementById('generator-section');
      generatorSection?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Navigation */}
      <nav className="fixed top-0 w-full bg-white/95 backdrop-blur-md shadow-sm border-b border-gray-200 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center">
              <div className="text-2xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent mr-3">
                🚀
              </div>
              <div>
                <h1 className="text-xl font-bold text-gray-900">
                  Scout AI
                </h1>
                <p className="text-sm text-gray-600">
                  Newsletter Generator
                </p>
              </div>
            </div>
            
            {/* API Health Indicator */}
            <div className="flex items-center space-x-4">
              {apiHealth === null ? (
                <div className="flex items-center text-gray-500">
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-pulse mr-2"></div>
                  <span className="text-sm">Connecting...</span>
                </div>
              ) : apiHealth ? (
                <div className="flex items-center text-green-600">
                  <div className="w-2 h-2 bg-green-500 rounded-full mr-2"></div>
                  <span className="text-sm font-medium">Online</span>
                </div>
              ) : (
                <div className="flex items-center text-red-600">
                  <div className="w-2 h-2 bg-red-500 rounded-full mr-2"></div>
                  <span className="text-sm font-medium">Offline</span>
                  <button 
                    onClick={checkApiHealth}
                    className="ml-2 text-xs bg-red-100 hover:bg-red-200 text-red-700 px-2 py-1 rounded"
                  >
                    Retry
                  </button>
                </div>
              )}
              
              {showHero && (
                <button
                  onClick={scrollToGenerator}
                  className="bg-gradient-to-r from-blue-600 to-purple-600 text-white px-4 py-2 rounded-lg font-medium hover:shadow-lg transition-all duration-200"
                >
                  Try Now
                </button>
              )}
            </div>
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      {showHero && (
        <section className="relative pt-16 pb-20 bg-gradient-to-br from-blue-50 via-indigo-50 to-purple-50 overflow-hidden">
          {/* Background decoration */}
          <div className="absolute inset-0">
            <div className="absolute top-1/4 left-1/4 w-72 h-72 bg-blue-300 rounded-full mix-blend-multiply filter blur-xl opacity-20 animate-blob"></div>
            <div className="absolute top-1/3 right-1/4 w-72 h-72 bg-purple-300 rounded-full mix-blend-multiply filter blur-xl opacity-20 animate-blob animation-delay-2000"></div>
            <div className="absolute bottom-1/4 left-1/3 w-72 h-72 bg-pink-300 rounded-full mix-blend-multiply filter blur-xl opacity-20 animate-blob animation-delay-4000"></div>
          </div>

          <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-20">
            <div className="text-center">
              <div className="inline-flex items-center px-4 py-2 rounded-full bg-blue-100 text-blue-800 text-sm font-medium mb-8">
                <span className="w-2 h-2 bg-blue-500 rounded-full mr-2 animate-pulse"></span>
                AI-Powered Newsletter Generation
              </div>
              
              <h1 className="text-5xl md:text-7xl font-extrabold text-gray-900 mb-6 leading-tight">
                Professional 
                <span className="bg-gradient-to-r from-blue-600 via-purple-600 to-pink-600 bg-clip-text text-transparent"> 
                  AI Newsletters
                </span>
                <br />
                in 60 Seconds
              </h1>
              
              <p className="max-w-3xl mx-auto text-xl md:text-2xl text-gray-600 mb-12 leading-relaxed">
                Transform any topic into a professional newsletter with our 5-stage AI pipeline. 
                <span className="font-semibold text-gray-900"> Research, write, assess, and perfect</span> – all automatically.
              </p>

              <div className="flex flex-col sm:flex-row gap-4 justify-center items-center mb-16">
                <button
                  onClick={scrollToGenerator}
                  className="w-full sm:w-auto bg-gradient-to-r from-blue-600 to-purple-600 text-white px-8 py-4 rounded-xl font-semibold text-lg hover:shadow-2xl hover:scale-105 transition-all duration-300 flex items-center justify-center"
                >
                  <svg className="w-5 h-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M10.293 3.293a1 1 0 011.414 0l6 6a1 1 0 010 1.414l-6 6a1 1 0 01-1.414-1.414L14.586 11H3a1 1 0 110-2h11.586l-4.293-4.293a1 1 0 010-1.414z" clipRule="evenodd" />
                  </svg>
                  Generate Newsletter Now
                </button>
                <button className="w-full sm:w-auto text-gray-700 px-8 py-4 rounded-xl font-semibold text-lg hover:bg-white/80 transition-all duration-200 flex items-center justify-center">
                  <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.828 14.828a4 4 0 01-5.656 0M9 10h1m4 0h1m-6 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                  See Live Demo
                </button>
              </div>

              {/* Stats */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8 max-w-4xl mx-auto">
                <div className="text-center">
                  <div className="text-3xl md:text-4xl font-bold text-gray-900 mb-2">5-Stage</div>
                  <div className="text-gray-600">AI Pipeline</div>
                </div>
                <div className="text-center">
                  <div className="text-3xl md:text-4xl font-bold text-gray-900 mb-2">&lt;60s</div>
                  <div className="text-gray-600">Generation Time</div>
                </div>
                <div className="text-center">
                  <div className="text-3xl md:text-4xl font-bold text-gray-900 mb-2">95%</div>
                  <div className="text-gray-600">Quality Score</div>
                </div>
              </div>
            </div>
          </div>
        </section>
      )}

      {/* Features Section */}
      {showHero && (
        <section className="py-20 bg-white">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="text-center mb-16">
              <h2 className="text-4xl md:text-5xl font-bold text-gray-900 mb-4">
                How It Works
              </h2>
              <p className="text-xl text-gray-600 max-w-3xl mx-auto">
                Our advanced AI pipeline ensures every newsletter is professional, accurate, and engaging
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-5 gap-8">
              {initialStages.map((stage, index) => (
                <div key={stage.id} className="relative">
                  <div className="bg-gradient-to-br from-white to-gray-50 rounded-2xl p-6 shadow-lg hover:shadow-xl transition-all duration-300 border border-gray-200 hover:border-blue-300 h-full">
                    <div className="text-4xl mb-4">{stage.icon}</div>
                    <div className="text-sm font-semibold text-blue-600 mb-2">Stage {index + 1}</div>
                    <h3 className="text-lg font-bold text-gray-900 mb-3">{stage.name}</h3>
                    <p className="text-gray-600 text-sm leading-relaxed">{stage.description}</p>
                  </div>
                  {index < initialStages.length - 1 && (
                    <div className="hidden md:block absolute top-1/2 -right-4 transform -translate-y-1/2 z-10">
                      <svg className="w-8 h-8 text-blue-300" fill="currentColor" viewBox="0 0 20 20">
                        <path fillRule="evenodd" d="M10.293 3.293a1 1 0 011.414 0l6 6a1 1 0 010 1.414l-6 6a1 1 0 01-1.414-1.414L14.586 11H3a1 1 0 110-2h11.586l-4.293-4.293a1 1 0 010-1.414z" clipRule="evenodd" />
                      </svg>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Main Content */}
      <main className={`${showHero ? 'py-20 bg-gray-50' : 'pt-20'}`} id="generator-section">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          {/* Error Message */}
          {appState.error && (
            <div className="mb-8 bg-red-50 border border-red-200 rounded-xl p-6">
              <div className="flex items-center">
                <svg className="w-6 h-6 text-red-600 mr-3" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                </svg>
                <div>
                  <h3 className="text-red-900 font-semibold text-lg">Generation Failed</h3>
                  <p className="text-red-800">{appState.error}</p>
                </div>
              </div>
              <button
                onClick={resetState}
                className="mt-4 bg-red-600 hover:bg-red-700 text-white px-6 py-3 rounded-lg font-semibold transition-colors"
              >
                Try Again
              </button>
            </div>
          )}

          {/* Topic Input */}
          {!appState.newsletter && (
            <TopicInput 
              onSubmit={handleTopicSubmit}
              isLoading={appState.isGenerating}
              disabled={apiHealth === false}
            />
          )}

          {/* Processing Stages */}
          {(appState.isGenerating || appState.newsletter) && (
            <ProcessingStages 
              stages={appState.stages}
              currentStage={appState.currentStage}
              isProcessing={appState.isGenerating}
            />
          )}

          {/* Newsletter Output */}
          {appState.newsletter && (
            <div className="space-y-8">
              <NewsletterOutput 
                newsletter={appState.newsletter}
                onNewsletter={handleGenerateAnother}
              />
              
              <QualityScore 
                qualityCheck={appState.newsletter.quality_check}
              />
            </div>
          )}
        </div>
      </main>

      {/* Footer */}
      {showHero && (
        <footer className="bg-gray-900 text-white py-16">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
              <div className="md:col-span-2">
                <div className="flex items-center mb-4">
                  <div className="text-2xl font-bold bg-gradient-to-r from-blue-400 to-purple-400 bg-clip-text text-transparent mr-3">
                    🚀
                  </div>
                  <div>
                    <h3 className="text-xl font-bold">Scout AI Newsletter Generator</h3>
                    <p className="text-gray-400">Professional AI-powered newsletter creation</p>
                  </div>
                </div>
                <p className="text-gray-400 max-w-md">
                  Transform any topic into a professional newsletter with our advanced 5-stage AI pipeline. 
                  Built with modern technologies for exceptional performance.
                </p>
              </div>
              
              <div>
                <h4 className="text-lg font-semibold mb-4">Architecture</h4>
                <ul className="space-y-2 text-gray-400">
                  <li>• React + TypeScript Frontend</li>
                  <li>• FastAPI Python Backend</li>
                  <li>• 5-Stage AI Pipeline</li>
                  <li>• Real-time Processing</li>
                </ul>
              </div>
              
              <div>
                <h4 className="text-lg font-semibold mb-4">AI Technologies</h4>
                <ul className="space-y-2 text-gray-400">
                  <li>• OpenAI GPT-4 Integration</li>
                  <li>• Tavily Search API</li>
                  <li>• Smart Quality Assessment</li>
                  <li>• Auto-improvement System</li>
                </ul>
              </div>
            </div>
            
            <div className="border-t border-gray-800 pt-8 mt-8 text-center">
              <p className="text-gray-400">
                Built with modern technologies for professional newsletter generation
              </p>
            </div>
          </div>
        </footer>
      )}
    </div>
  );
};

export default App;
